          "sql": "SELECT 'abn' src, span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) med_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Internal' GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), round(quantile_cont(duration,0.5)/1e6,1), round(quantile_cont(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Internal' GROUP BY 1,2 ORDER BY 2,1",
          "claim": "Travel-plan controller methods (getByCheapest, getByMinStation, getByQuickest) median self-time rose from about 0.4-0.5s to 1.1-1.6s."
        },
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT DISTINCT trace_id FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND span_name LIKE '%cheapest%' LIMIT 1) SELECT time, service_name, span_name, span_id, parent_span_id, attr_span_kind, duration/1e6 ms, attr_status_code, attr_k8s_pod_name FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM t) ORDER BY time",
          "claim": "In one trace the travel-plan controller takes 3285ms while its only child call to route-plan takes 412ms."
        },
        {
          "kind": "metric",
          "sql": "WITH a AS (SELECT metric, avg(value) v FROM abnormal_metrics WHERE service_name='ts-travel-plan-service' GROUP BY 1), n AS (SELECT metric, avg(value) v FROM normal_metrics WHERE service_name='ts-travel-plan-service' GROUP BY 1) SELECT coalesce(a.metric,n.metric) m, round(n.v,3) norm_avg, round(a.v,3) abn_avg FROM a FULL JOIN n USING(metric) WHERE coalesce(a.metric,n.metric) IN ('container.cpu.usage','k8s.pod.memory.working_set','jvm.cpu.time','jvm.memory.used') ORDER BY 1",
          "claim": "Travel-plan container CPU, memory and JVM CPU time are flat or lower in the abnormal period, so there is no resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn-ui->tp' src, span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) med_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%travelPlan%' AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 2",
          "claim": "User-facing ui-dashboard travelPlan requests now take a median of about 1.1-1.6s and p95 about 3.5s."
        }
      ]
    }
  ]
}
